def safe_div(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None

test_cases = 4
passed_tests = 0

for i in range(test_cases):
    try:
        result = safe_div(10, 2)
        assert result == 5, f"Test {i+1} failed: Expected 5, got {result}"
        passed_tests += 1
    except AssertionError as e:
        print(e)

    try:
        result = safe_div(-10, -2)
        assert result == 5, f"Test {i+1} failed: Expected 5, got {result}"
        passed_tests += 1
    except AssertionError as e:
        print(e)

    try:
        result = safe_div(0, 10)
        assert result == 0, f"Test {i+1} failed: Expected 0, got {result}"
        passed_tests += 1
    except AssertionError as e:
        print(e)

    try:
        result = safe_div(7.5, 3)
        assert result == 2.5, f"Test {i+1} failed: Expected 2.5, got {result}"
        passed_tests += 1
    except AssertionError as e:
        print(e)

print(f'PASSED: {passed_tests}/{test_cases}')
